func uniqueStrings(values []string) []string {
	seen := map[string]struct{}{}
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value == "" {
			continue
		}
		seen[value] = struct{}{}
	}
	return sortedKeys(seen)
}

2. internal/sem/search.go:5194-5206 score=18.2253 symbol=appendUnique kind=function signals=body,symbol-name,graph:callers,complete-symbol
func appendUnique(values []string, additions ...string) []string {
	seen := make(map[string]bool, len(values)+len(additions))
	for _, value := range values {
		seen[value] = true
	}
	for _, value := range additions {
		if value != "" && !seen[value] {
			seen[value] = true
			values = append(values, value)
		}
	}
	return values
}

3. internal/sem/cpp_specialization.go:149-175 score=16.4028 symbol=applyCppSpecializationAliases kind=function signals=body,symbol-usage,complete-symbol
func applyCppSpecializationAliases(symbols []SymbolRecord) {
	aliasesByContainer := map[string][]string{}
	for i := range symbols {
		symbol := &symbols[i]
		if !typeLikeKind(symbol.Kind) {
			continue
		}
		aliases := cppSpecializationAliases(symbol.Language, symbol.Name, symbol.Signature)
		if len(aliases) == 0 {
			continue
		}
		symbol.Aliases = appendUnique(symbol.Aliases, aliases...)
		aliasesByContainer[symbol.ID] = aliases
	}
	if len(aliasesByContainer) == 0 {
		return
	}
	for i := range symbols {
		symbol := &symbols[i]
		if symbol.ContainerID == "" || typeLikeKind(symbol.Kind) {
			continue
		}
		if aliases := aliasesByContainer[symbol.ContainerID]; len(aliases) > 0 {
			symbol.Aliases = appendUnique(symbol.Aliases, aliases...)
		}
	}
}

