 312	// ensureContainedInRepo refuses a write target whose resolution leaves the repository. It is a
 313	// preflight only: root.Stat resolves the same way the write does but is not atomic with it, so
 314	// writeContainedFile below remains the boundary that actually holds. Its job is to turn an
 315	// escaping alias into one clear error before any file is created.
 316	//
 317	// A missing target is not an escape. init-agents legitimately creates all four paths, and the
 318	// documented dangling alias (CLAUDE.md -> AGENTS.md before AGENTS.md exists) resolves to
 319	// fs.ErrNotExist inside the root.
 320	//
 321	// Nor is an unreadable directory, a symlink loop, or an I/O error. Every remaining stat failure
 322	// still aborts the install, but only the ones os.Root attributes to confinement are described as
 323	// one; see isRootEscape.
 324	//
 325	// A path the walk below cannot resolve as spelled (errUnresolvableAlias) is neither. It has to be
 326	// checked before the missing-target case because it arrives as the kernel's own ENOENT/ENOTDIR
 327	// and would otherwise read as a file init-agents may create — and it is not creatable: an
 328	// O_CREAT open of that same spelling fails exactly as the stat did.
 329	func ensureContainedInRepo(root *os.Root, name, path string, createsParents bool, plannedDirs ...string) error {
 330		var err error
 331		if createsParents {
 332			var resolved string
 333			resolved, err = resolveContainedDirectoryName(root, name)
 334			if err == nil {
 335				_, err = statResolvedContained(root, resolved)
 336			}
 337		} else {
 338			_, err = statContainedFile(root, name)
 339		}
 340		switch {
 341		case errors.Is(err, errUnresolvableAlias):
 342			// Not an escape and not a target to create: the chain names its landing only
 343			// after a ".." the kernel could not have taken, so there is nothing to write.
 344			return fmt.Errorf(
 345				"%s: refusing to write through a link the filesystem cannot resolve (%w); "+
 346					"the target is not traversable as written, so repoint or remove the link, then rerun init-agents",
 347				path, err,
 348			)
 349		case err == nil:
 350			return nil
 351		case errors.Is(err, fs.ErrNotExist):
 352			if createsParents {
 353				return nil
 354			}
 355			if parentErr := ensureMissingTargetParent(root, name, plannedDirs); parentErr != nil {
 356				return fmt.Errorf(
 357					"%s: refusing to write through a link the filesystem cannot resolve (%w); "+
 358						"the target's parent directory will not exist when it is written, so create it or repoint the link, then rerun init-agents",
 359					path, parentErr,
 360				)
 361			}
 362			return nil
 363		case errors.Is(err, errGitDirManagedTarget):
 364			return fmt.Errorf(
 365				"%s: %w; init-agents installs instruction files, and none of them belongs in the "+
 366					"git directory, so repoint or remove the link, then rerun init-agents",
 367				path, err,
 368			)
