 463	// another after alias resolution. AGENTS.md and CLAUDE.md may intentionally share a file, but the
 464	// guide must stay distinct, and no file target may be an ancestor that MkdirAll will turn into a
 465	// directory. Checking before reads and writes preserves the all-target preflight guarantee.
 466	func validateManagedTargetTopology(root *os.Root, guideDir, guide, agents, claude string) error {
 467		dirName, dirInfo, err := resolvedManagedTarget(root, guideDir, true)
 468		if err != nil {
 469			return err
 470		}
 471		if dirInfo != nil && !dirInfo.IsDir() {
 472			return fmt.Errorf("%s: expected a directory, found %s", guideDir, fileTypeName(dirInfo.Mode()))
 473		}
 474		guideName, guideInfo, err := resolvedManagedTarget(root, guide, false)
 475		if err != nil {
 476			return err
 477		}
 478		if guideInfo != nil && !guideInfo.Mode().IsRegular() {
 479			return fmt.Errorf("%s: expected a regular file, found %s", guide, fileTypeName(guideInfo.Mode()))
 480		}
 481		if pathIsAncestorOrSame(guideName, dirName) {
 482			return fmt.Errorf("%s: managed guide collides with directory target %s", guide, guideDir)
 483		}
