 485		for _, instruction := range []string{agents, claude} {
 486			instructionName, instructionInfo, resolveErr := resolvedManagedTarget(root, instruction, false)
 487			if resolveErr != nil {
 488				return resolveErr
 489			}
 490			if instructionInfo != nil && !instructionInfo.Mode().IsRegular() {
 491				return fmt.Errorf("%s: expected a regular file, found %s", instruction, fileTypeName(instructionInfo.Mode()))
 492			}
 493			if pathIsAncestorOrSame(instructionName, dirName) {
 494				return fmt.Errorf("%s: instruction target will be created as a directory by %s", instruction, guideDir)
 495			}
 496			if sameResolvedName(guideName, instructionName) ||
 497				(guideInfo != nil && instructionInfo != nil && os.SameFile(guideInfo, instructionInfo)) {
 498				return fmt.Errorf("%s and %s resolve to the same managed file", guide, instruction)
