 504	func resolvedManagedTarget(root *os.Root, name string, directory bool) (string, os.FileInfo, error) {
 505		var (
 506			resolved string
 507			err      error
 508		)
 509		if directory {
 510			resolved, err = resolveContainedDirectoryName(root, name)
 511		} else {
 512			resolved, err = resolveContainedName(root, name)
 513		}
 514		if err != nil {
 515			return "", nil, err
 516		}
 517		info, err := statResolvedContained(root, resolved)
 518		if errors.Is(err, fs.ErrNotExist) {
 519			return resolved, nil, nil
 520		}
 521		return resolved, info, err
