 908	// refuseNonInstructionLanding refuses a managed target that resolves onto an EXISTING file which is
 909	// not an agent-instruction file.
 910	//
 911	// The git-directory refusals above name one destination each. That is a denylist, and a denylist of
 912	// destinations cannot be finished: `CLAUDE.md -> Makefile`, `-> .github/workflows/ci.yml` and
 913	// `-> .envrc` were all measured on this branch appending the managed block to the victim's real
 914	// build, CI and environment files, exit 0 — and every build system, task runner and shell
 915	// initialisation file yet to be invented is another entry someone has to remember to add. The list
 916	// that CAN be finished is the list of things init-agents is for: docs/agents.md offers the alias so
 917	// that AGENTS.md and CLAUDE.md may share ONE INSTRUCTION FILE, so an alias that lands anywhere else
 918	// is not a use of the feature, and refusing it costs the documented case nothing.
 919	//
 920	// Three landings are deliberately not refused, and each is a case where there is nothing to
 921	// protect:
 922	//
 923	//   - A landing that DOES NOT EXIST. init-agents creates all of its targets, and the documented
 924	//     dangling alias (CLAUDE.md -> AGENTS.md before AGENTS.md exists) depends on it. Nothing is
 925	//     destroyed: the file this command creates holds this command's own markdown, mode 0644, and
 926	//     shows up untracked in `git status` — the harm this refusal exists for is the SILENT rewrite
 927	//     of a file that was already doing a job.
 928	//   - A landing that already carries this command's own output. A file init-agents wrote once must
 929	//     stay writable on the next run whatever it is named, or a first run would succeed and every
 930	//     later one fail.
 931	//   - A landing that is not a regular file, or cannot be stat'ed. Those are not this refusal's
 932	//     question; the operation that follows reports them for what they are.
 933	func refuseNonInstructionLanding(root *os.Root, name, resolved string) error {
 934		if isInstructionFileName(filepath.Base(resolved)) {
 935			return nil
 936		}
 937		info, err := root.Stat(resolved)
 938		if err != nil || !info.Mode().IsRegular() {
 939			return nil
 940		}
 941		if landingCarriesManagedContent(root, resolved) {
 942			return nil
 943		}
 944		return fmt.Errorf(
 945			"%w: %s resolves to %s, which is not an agent-instruction file; init-agents installs its managed block only into instruction files, so alias it to one",
 946			errNonInstructionManagedTarget, name, filepath.ToSlash(resolved),
 947		)
 948	}
