 950	// landingCarriesManagedContent reports whether a landing already holds output this command wrote:
 951	// the managed pointer block, or the guide's own heading.
 952	func landingCarriesManagedContent(root *os.Root, resolved string) bool {
 953		file, err := root.Open(resolved)
 954		if err != nil {
 955			return false
 956		}
 957		defer file.Close()
 958		content, err := io.ReadAll(io.LimitReader(file, maxManagedLandingBytes))
