 965	func resolveContainedLanding(root *os.Root, name string, allowMissingDirectory bool) (string, error) {
 966		pending := splitPathComponents(name)
 967		var resolved []string
 968		requiresDirectory := false
 969		fullyQualifiedTarget := false
 970		var windowsFinalDirectory *bool
 971		for hops := 0; len(pending) > 0; {
 972			component := pending[0]
 973			pending = pending[1:]
 974			switch component {
 975			case "":
 976				// A trailing separator requires the landing to be a directory. Preserve that
 977				// requirement in the name handed to os.Root; an empty component in the middle
 978				// is just a repeated separator.
 979				if len(pending) == 0 {
 980					requiresDirectory = true
 981				}
 982				continue
 983			case ".":
 984				// A terminal "/." carries the same directory requirement as a trailing
 985				// separator. Interior dots may be dropped because the following component
 986				// still forces the prefix to be traversed as a directory.
 987				if len(pending) == 0 {
 988					requiresDirectory = true
 989				}
 990				continue
 991			case "..":
 992				if len(resolved) == 0 {
 993					// Above the root. Let os.Root refuse the real chain.
 994					return name, nil
 995				}
 996				if err := ensureParentTraversable(root, resolved); err != nil {
 997					return "", err
 998				}
 999				resolved = resolved[:len(resolved)-1]
1000				continue
1001			}
1002			candidate := filepath.Join(append(slices.Clone(resolved), component)...)
1003			info, err := root.Lstat(candidate)
1004			if err != nil {
1005				if errors.Is(err, fs.ErrNotExist) {
1006					resolved = append(resolved, component)
1007					continue
1008				}
1009				return "", err
1010			}
1011			isSymlink := info.Mode()&os.ModeSymlink != 0
1012			isWindowsReparsePoint := runtime.GOOS == "windows" && info.Mode()&os.ModeIrregular != 0
1013			if !isSymlink && !isWindowsReparsePoint {
1014				resolved = append(resolved, component)
1015				continue
1016			}
1017			var target string
1018			if runtime.GOOS == "windows" {
1019				rawTarget, available, rawErr := windowsRawReparseTarget(root.Name(), candidate, info)
1020				if rawErr != nil {
1021					return "", fmt.Errorf("%w: cannot inspect raw Windows reparse target: %v", errUnresolvableAlias, rawErr)
1022				}
1023				if !available {
1024					// Since Go 1.23, Windows reports every reparse point as
1025					// ModeIrregular. Preserve tags that do not participate in path
1026					// resolution for the ordinary file-type check below.
1027					if isWindowsReparsePoint && !isSymlink {
1028						resolved = append(resolved, component)
1029						continue
1030					}
1031					return "", fmt.Errorf("%w: cannot inspect raw Windows reparse target", errUnresolvableAlias)
1032				}
1033				// Resolve the raw target from the same reparse-buffer snapshot that was
1034				// screened, so malformed offsets never reach Readlink's unsafe parser and
1035				// an in-place update cannot pair an unchecked target with this walk.
1036				target = rawTarget
1037			} else {
1038				var readErr error
1039				target, readErr = root.Readlink(candidate)
1040				if readErr != nil {
1041					return "", readErr
1042				}
1043			}
1044			if runtime.GOOS == "windows" {
1045				linkDirectory, ok := windowsLinkRequiresDirectory(info)
1046				if !ok {
1047					return "", fmt.Errorf("%w: cannot determine Windows link type for %s", errUnresolvableAlias, candidate)
1048				}
1049				if len(pending) > 0 {
1050					if !linkDirectory {
1051						return "", fmt.Errorf("%w: Windows file symlink %s cannot be traversed as a directory", errUnresolvableAlias, candidate)
1052					}
1053				} else {
1054					if windowsFinalDirectory != nil && *windowsFinalDirectory != linkDirectory {
1055						return "", fmt.Errorf("%w: Windows link chain changes its required target type", errUnresolvableAlias)
1056					}
1057					required := linkDirectory
1058					windowsFinalDirectory = &required
1059				}
1060			}
1061			hops++
1062			if filepath.IsAbs(target) || filepath.VolumeName(target) != "" ||
1063				(len(target) > 0 && os.IsPathSeparator(target[0])) {
1064				fullyQualifiedTarget = true
1065			}
1066			if hops > containedLinkHopLimit(fullyQualifiedTarget) {
1067				return "", &fs.PathError{Op: "resolve", Path: name, Err: syscall.ELOOP}
1068			}
1069			if !filepath.IsAbs(target) {
1070				// Windows drive-relative (C:foo) and drive-rooted (\foo) targets are not
1071				// link-relative even though filepath.IsAbs reports false. A drive-relative
1072				// target has process-global semantics and is left for os.Root to reject.
1073				if filepath.VolumeName(target) != "" {
1074					return name, nil
1075				}
1076				if len(target) > 0 && os.IsPathSeparator(target[0]) {
1077					// A Windows drive-rooted target (\foo) is anchored at the link's
1078					// volume. Expand that volume without cleaning the suffix so a legitimate
1079					// in-repository target can be judged by filesystem identity.
1080					target = filepath.VolumeName(root.Name()) + target
1081				} else {
1082					if runtime.GOOS == "windows" {
1083						// Windows applies lexical cleaning to the entire path before it
1084						// opens any component, including after substituting a relative
1085						// reparse target. Rebuild that whole path here so a/../b has the
1086						// same meaning as b even when a is missing or not a directory.
1087						combined := strings.Join(resolved, string(filepath.Separator))
1088						if combined != "" {
1089							combined += string(filepath.Separator)
1090						}
1091						combined += target
1092						if len(pending) > 0 {
1093							combined += string(filepath.Separator) + strings.Join(pending, string(filepath.Separator))
1094						}
1095						resolved = resolved[:0]
1096						pending = splitPathComponents(cleanWindowsPathPreservingDirectory(combined))
1097						continue
1098					}
1099					pending = append(splitPathComponents(target), pending...)
1100					continue
1101				}
1102			}
1103			if runtime.GOOS == "windows" {
1104				if windowsPathDisablesCleaning(target) {
1105					// Extended/device paths disable parts of Win32 parsing that the
1106					// confined relative operations below necessarily apply (including
1107					// separator and trailing-dot handling). There is no generally safe
1108					// spelling-preserving translation, so fail before any write.
1109					return "", fmt.Errorf("%w: unsupported Windows extended or device path", errUnresolvableAlias)
1110				}
1111				target = cleanWindowsPathPreservingDirectory(target)
1112			}
1113			rel, prefixHops, ok := repoRelativeName(root.Name(), target)
1114			if !ok {
1115				// Lands outside. Let os.Root refuse the real chain.
1116				return name, nil
1117			}
1118			hops += prefixHops
1119			if hops > containedLinkHopLimit(fullyQualifiedTarget) {
1120				return "", &fs.PathError{Op: "resolve", Path: name, Err: syscall.ELOOP}
1121			}
1122			// An absolute target is anchored at the root, so the walk restarts there.
1123			resolved = resolved[:0]
1124			pending = append(splitPathComponents(rel), pending...)
1125		}
1126		result := "."
1127		if len(resolved) > 0 {
1128			result = filepath.Join(resolved...)
1129		}
1130		if windowsFinalDirectory != nil {
1131			info, err := statResolvedContained(root, result)
1132			switch {
1133			case err == nil && info.IsDir() != *windowsFinalDirectory:
1134				return "", fmt.Errorf("%w: Windows link target type does not match the link", errUnresolvableAlias)
1135			case errors.Is(err, fs.ErrNotExist) && *windowsFinalDirectory != allowMissingDirectory:
1136				return "", fmt.Errorf("%w: dangling Windows link type does not match the managed target", errUnresolvableAlias)
1137			case err != nil && !errors.Is(err, fs.ErrNotExist):
1138				return "", err
1139			}
1140		}
1141		if requiresDirectory {
1142			result += string(filepath.Separator)
1143			if _, err := root.Lstat(result); err != nil {
1144				if allowMissingDirectory && errors.Is(err, fs.ErrNotExist) {
1145					return result, nil
1146				}
1147				return "", fmt.Errorf("%w: %v", errUnresolvableAlias, err)
1148			}
1149		}
1150		if len(resolved) == 0 {
1151			// The chain resolved to the repository root itself.
1152			return result, nil
1153		}
1154		return result, nil
1155	}
