1157	// splitPathComponents preserves empty and terminal components while accepting every separator
1158	// the host accepts. In particular, Windows treats both '\\' and '/' as separators; leaving '/'
1159	// embedded in a component would let filepath.Join clean a raw "missing/../victim" before the
1160	// component walker can ask the filesystem whether "missing" is traversable.
1161	func splitPathComponents(path string) []string {
1162		components := make([]string, 0, strings.Count(path, string(filepath.Separator))+1)
1163		start := 0
1164		for i := 0; i < len(path); i++ {
1165			if os.IsPathSeparator(path[i]) {
1166				components = append(components, path[start:i])
1167				start = i + 1
1168			}
1169		}
1170		return append(components, path[start:])
1171	}
