1173	func cleanWindowsPathPreservingDirectory(path string) string {
1174		requiresDirectory := len(path) > 0 && os.IsPathSeparator(path[len(path)-1])
1175		if !requiresDirectory {
1176			components := splitPathComponents(path)
1177			requiresDirectory = len(components) > 0 && components[len(components)-1] == "."
1178		}
1179		cleaned := filepath.Clean(path)
1180		if requiresDirectory && (len(cleaned) == 0 || !os.IsPathSeparator(cleaned[len(cleaned)-1])) {
1181			cleaned += string(filepath.Separator)
1182		}
1183		return cleaned
1184	}
