1192	// errUnresolvableAlias marks an alias spelling that does not name a creatable managed target.
1193	// This includes a ".." over a component the kernel cannot traverse and a file target ending in
1194	// "/" or "/.". Folding the kernel's answer in as text rather than wrapping it keeps
1195	// os.IsNotExist from reading either shape as the ordinary creatable-file case.
1196	var errUnresolvableAlias = errors.New("link target is not traversable as written")
