1198	// ensureParentTraversable asks the kernel whether ".." may be taken out of the last component of
1199	// resolved, and is what makes collapsing it equivalent to the walk the kernel would perform.
1200	//
1201	// filepath.Abs, filepath.Join and filepath.Clean collapse ".." LEXICALLY — before a single
1202	// component is opened — so text alone cannot tell a legal traversal from one that never happens.
1203	// A prefix that does not exist, is not a directory, or cannot be searched stops the kernel with
1204	// ENOENT/ENOTDIR/EACCES; erasing it as text instead leaves the remaining elements naming a file
1205	// the kernel would never have reached, and init-agents would write there.
1206	//
1207	// os.Root is the oracle rather than a rule reconstructed here: it resolves each component with
1208	// openat, ".." included, so handing it the prefix with the ".." still attached returns exactly
1209	// the kernel's own verdict — including reasons this code does not enumerate, such as a directory
1210	// without search permission. The probe path is assembled with strings.Join, not filepath.Join,
1211	// because Join cleans: it would delete the ".." this probe exists to send to the kernel.
1212	//
1213	// The pop itself stays lexical, and is correct once the probe passes: resolved holds only
1214	// components already stripped of symlinks, so its parent is its textual parent.
1215	func ensureParentTraversable(root *os.Root, resolved []string) error {
1550	
1551	func relativeSuffixIfRoot(rootInfo os.FileInfo, target string, prefixEnd int) (string, bool) {
1552		info, err := os.Stat(target[:prefixEnd])
1553		if err != nil || !os.SameFile(rootInfo, info) {
1554			return "", false
1555		}
1556		suffix := target[prefixEnd:]
1557		for len(suffix) > 0 && os.IsPathSeparator(suffix[0]) {
1558			suffix = suffix[1:]
1559		}
1560		if suffix == "" {
1561			return ".", true
1562		}
1563		return suffix, true
1564	}
