1566	// statContainedFile is os.Stat confined to root. It follows a link that stays inside the
1567	// repository — os.Root does the following, so the boundary is enforced by the same openat walk the
1568	// writes use — and the FileInfo it returns describes the TARGET inode, which is what os.SameFile
1569	// needs to recognize the documented AGENTS.md/CLAUDE.md alias.
1570	func statContainedFile(root *os.Root, name string) (os.FileInfo, error) {
1571		resolved, err := resolveContainedName(root, name)
1572		if err != nil {
1573			return nil, err
1574		}
1575		return statResolvedContained(root, resolved)
1576	}
