1578	// readContainedFile is os.ReadFile confined to root and bounded by limit bytes.
1579	//
1580	// Reading through the root rather than through the absolute path is not redundant with the
1581	// preflight. ensureContainedInRepo is explicitly not atomic with what follows, so a link swapped
1582	// to an outside file after the preflight and restored before the write would otherwise have that
1583	// file's contents read in and then written back into the repository under the managed block. The
1584	// escape has to be refused at the read too, not only at the preflight and the write.
1585	//
1586	// The limit is enforced on the read itself rather than on a preceding Stat, for the same
1587	// non-atomicity reason: a file that grows between the check and the read would defeat a
1588	// Stat-based gate, and a growing file is exactly the case the limit exists for. One byte past
1589	// the limit is requested so a file sitting exactly on it is still accepted, and anything larger
1590	// is refused rather than truncated — a truncated instruction file would be written back over the
1591	// user's own text, which is a far worse outcome than a refusal.
1592	func readContainedFile(root *os.Root, name string, limit int64) ([]byte, error) {
1593		resolved, err := resolveContainedName(root, name)
1594		if err != nil {
1595			return nil, err
1596		}
1597		file, err := root.Open(resolved)
1598		if err != nil {
1599			return nil, err
1600		}
1601		defer file.Close()
1602		content, err := io.ReadAll(io.LimitReader(file, limit+1))
1603		if err != nil {
1604			return nil, err
1605		}
1606		if int64(len(content)) > limit {
1607			return nil, errContainedFileTooLarge
1608		}
1609		return content, nil
1610	}
