1612	// writeContainedFile is os.WriteFile confined to root. The perm argument applies only when the
1613	// file is created, matching os.WriteFile, so an existing file keeps its mode.
1614	func writeContainedFile(root *os.Root, name string, content []byte, perm os.FileMode, managed ...string) error {
1615		resolved, err := resolveContainedName(root, name)
1616		if err != nil {
1617			return err
1618		}
1619		// O_TRUNC is deliberately NOT in this open, and the file is judged from the
1620		// HANDLE rather than from the resolved name.
1621		//
1622		// Both follow from the same gap. resolveContainedName decides on a path, and
1623		// the path is not the thing written: OpenFile re-resolves it, so a link
1624		// swapped in between the two is followed (os.Root refuses a link that
1625		// ESCAPES the root, atomically, but follows one that stays inside — and
1626		// `.git` is inside). Judging the open handle removes the window, because the
1627		// handle IS what the write lands on.
1628		//
1629		// And truncation is already the damage. Opening `.git/config` with O_TRUNC
1630		// destroys it before any guard below can object, so the truncate happens
1631		// only after the handle has been accepted.
1632		file, err := root.OpenFile(resolved, os.O_WRONLY|os.O_CREATE, perm)
1633		if err != nil {
1634			return err
1635		}
1636		if err := refuseSharedInode(root, file, name, resolved, managed); err != nil {
1637			_ = file.Close()
1638			return err
1639		}
1640		if err := file.Truncate(0); err != nil {
1641			_ = file.Close()
1642			return err
1643		}
1644		_, writeErr := file.Write(content)
1645		closeErr := file.Close()
1646		if writeErr != nil {
1647			return writeErr
1648		}
1649		return closeErr
1650	}
