 336			}
 337		} else {
 338			_, err = statContainedFile(root, name)
 339		}
 340		switch {
 341		case errors.Is(err, errUnresolvableAlias):
 342			// Not an escape and not a target to create: the chain names its landing only
 343			// after a ".." the kernel could not have taken, so there is nothing to write.
 344			return fmt.Errorf(
 345				"%s: refusing to write through a link the filesystem cannot resolve (%w); "+
 346					"the target is not traversable as written, so repoint or remove the link, then rerun init-agents",
 347				path, err,
 348			)
 349		case err == nil:
 350			return nil
 351		case errors.Is(err, fs.ErrNotExist):
 352			if createsParents {
 353				return nil
 354			}
 355			if parentErr := ensureMissingTargetParent(root, name, plannedDirs); parentErr != nil {
 356				return fmt.Errorf(
 357					"%s: refusing to write through a link the filesystem cannot resolve (%w); "+
 358						"the target's parent directory will not exist when it is written, so create it or repoint the link, then rerun init-agents",
 359					path, parentErr,
