 363		case errors.Is(err, errGitDirManagedTarget):
 364			return fmt.Errorf(
 365				"%s: %w; init-agents installs instruction files, and none of them belongs in the "+
 366					"git directory, so repoint or remove the link, then rerun init-agents",
 367				path, err,
 368			)
 369		case errors.Is(err, errNonInstructionManagedTarget):
 370			// Named before isRootEscape for the same reason the case above is: this refusal is
 371			// raised by the resolver rather than by os.Root, so it carries no syscall errno and
 372			// would otherwise be reported as a repository escape — sending the reader to hunt a
 373			// link that leaves the root when the link never left it.
 374			return fmt.Errorf(
 375				"%s: %w, then rerun init-agents",
 376				path, err,
 377			)
 378		case isRootEscape(err):
