   392	// ensureMissingTargetParent distinguishes a creatable missing leaf from a path whose parent is
   393	// also absent. OpenFile creates only the leaf, so accepting the latter would let init-agents write
   394	// the guide and an earlier instruction file before the eventual ENOENT. plannedDirs are the
   395	// directories runInitAgents creates before any file write; an alias whose resolved parent is one
   396	// of those remains safely creatable.
   397	func ensureMissingTargetParent(root *os.Root, name string, plannedDirs []string) error {
   398		resolved, err := resolveContainedName(root, name)
   399		if err != nil {
   400			return err
   401		}
   402		parent := filepath.Dir(resolved)
   403		if parent == "." {
   404			return nil
   405		}
   406		info, err := root.Stat(parent)
   407		if err == nil {
   408			if info.IsDir() {
   409				return nil
   410			}
   411			return fmt.Errorf("%w: parent %q is not a directory", errUnresolvableAlias, parent)
   412		}
   413		if !errors.Is(err, fs.ErrNotExist) {
   414			return err
   415		}
   416		for _, planned := range plannedDirs {
   417			resolvedPlanned, resolveErr := resolveContainedDirectoryName(root, planned)
   418			if resolveErr == nil {
