   524	// statResolvedContained distinguishes a genuinely absent landing from an existing object the
   525	// host cannot follow. The distinction matters on Windows, where an unknown name-surrogate
   526	// reparse point can make Stat report ENOENT even though Lstat sees an entry; treating that as a
   527	// creatable leaf would defer failure until after another managed file had been written.
   528	func statResolvedContained(root *os.Root, resolved string) (os.FileInfo, error) {
   529		info, err := root.Stat(resolved)
